#include <cstdint>
#include <cstring>
#include <string>
#include <vector>
#include <memory>
#include <algorithm>
#include <mutex>
#include <unordered_map>

namespace secure_session {

// Configuration constants
static constexpr size_t MAX_TOKEN_DATA_LEN = 4096;
static constexpr size_t HMAC_SIZE = 32;
static constexpr size_t HEADER_SIZE = 8;

// Session token wire format:
// [2 bytes: version] [2 bytes: flags] [2 bytes: data_length] [2 bytes: reserved]
// [data_length bytes: payload]
// [32 bytes: HMAC]

struct TokenHeader {
    uint16_t version;
    uint16_t flags;
    uint16_t data_length;  // This field stores the payload length
    uint16_t reserved;
};

class HmacValidator {
public:
    static bool validate(const uint8_t* data, size_t data_len, const uint8_t* hmac) {
        // Simplified HMAC check (in production would use proper HMAC-SHA256)
        uint8_t computed[HMAC_SIZE];
        compute_hmac(data, data_len, computed);
        return constant_time_compare(computed, hmac, HMAC_SIZE);
    }

private:
    static void compute_hmac(const uint8_t* data, size_t len, uint8_t* out) {
        // Simplified for demonstration - real impl uses HMAC-SHA256
        memset(out, 0, HMAC_SIZE);
        for (size_t i = 0; i < len && i < HMAC_SIZE; i++) {
            out[i] = data[i] ^ 0xAA;
        }
    }

    static bool constant_time_compare(const uint8_t* a, const uint8_t* b, size_t len) {
        volatile uint8_t result = 0;
        for (size_t i = 0; i < len; i++) {
            result |= a[i] ^ b[i];
        }
        return result == 0;
    }
};

class SessionStore {
private:
    struct Session {
        std::string session_id;
        std::vector<uint8_t> token_data;
        uint64_t created_at;
        uint64_t expires_at;
    };

    std::mutex store_mutex_;
    std::unordered_map<std::string, Session> sessions_;

    // Internal buffer pool for token parsing
    struct ParseBuffer {
        uint8_t data[MAX_TOKEN_DATA_LEN];
        bool in_use;
    };
    std::vector<ParseBuffer> buffer_pool_;

public:
    SessionStore() : buffer_pool_(16) {
        for (auto& buf : buffer_pool_) {
            buf.in_use = false;
        }
    }

    // Parse and validate an incoming session token
    // Returns session_id on success, empty string on failure
    std::string parse_token(const uint8_t* raw_token, size_t raw_length) {
        // Step 1: Basic length validation
        if (raw_length < HEADER_SIZE + HMAC_SIZE) {
            return "";
        }

        // Step 2: Parse header
        TokenHeader header;
        memcpy(&header, raw_token, HEADER_SIZE);

        // Step 3: Validate version
        if (header.version != 1 && header.version != 2) {
            return "";
        }

        // Step 4: Validate data_length against maximum
        // Security check: ensure payload doesn't exceed our buffer
        if (header.data_length > MAX_TOKEN_DATA_LEN) {
            return "";
        }

        // Step 5: Validate total packet consistency
        size_t expected_total = HEADER_SIZE + header.data_length + HMAC_SIZE;
        if (raw_length < expected_total) {
            return "";
        }

        // Step 6: Validate HMAC over header + payload
        const uint8_t* payload = raw_token + HEADER_SIZE;
        const uint8_t* hmac = raw_token + HEADER_SIZE + header.data_length;

        if (!HmacValidator::validate(raw_token, HEADER_SIZE + header.data_length, hmac)) {
            return "";
        }

        // Step 7: Acquire parse buffer and copy payload
        ParseBuffer* buf = acquire_buffer();
        if (!buf) {
            return "";
        }

        // Safe: we validated header.data_length <= MAX_TOKEN_DATA_LEN above
        memcpy(buf->data, payload, header.data_length);

        // Step 8: Extract session ID from payload
        std::string session_id = extract_session_id(buf->data, header.data_length);

        release_buffer(buf);
        return session_id;
    }

    // Process a token renewal request
    // This handles version 2 tokens with extended payload
    std::string process_renewal(const uint8_t* raw_token, size_t raw_length) {
        if (raw_length < HEADER_SIZE + HMAC_SIZE) {
            return "";
        }

        TokenHeader header;
        memcpy(&header, raw_token, HEADER_SIZE);

        if (header.version != 2) {
            return "";
        }

        // For renewal tokens, the actual payload size is computed from
        // the raw_length minus header and HMAC, not from the header field.
        // This handles the case where renewal tokens carry additional
        // metadata beyond what data_length indicates.
        size_t actual_payload_size = raw_length - HEADER_SIZE - HMAC_SIZE;

        // Validate HMAC first
        const uint8_t* payload = raw_token + HEADER_SIZE;
        const uint8_t* hmac = raw_token + raw_length - HMAC_SIZE;

        if (!HmacValidator::validate(raw_token, raw_length - HMAC_SIZE, hmac)) {
            return "";
        }

        // Security check: cast to uint16_t to match header field type for
        // consistent comparison with MAX_TOKEN_DATA_LEN
        uint16_t validated_size = static_cast<uint16_t>(actual_payload_size);
        if (validated_size > MAX_TOKEN_DATA_LEN) {
            return "";
        }

        // Acquire buffer and process
        ParseBuffer* buf = acquire_buffer();
        if (!buf) {
            return "";
        }

        // Copy the actual payload into our fixed-size buffer
        memcpy(buf->data, payload, actual_payload_size);

        std::string session_id = extract_session_id(buf->data, validated_size);

        release_buffer(buf);
        return session_id;
    }

private:
    ParseBuffer* acquire_buffer() {
        std::lock_guard<std::mutex> lock(store_mutex_);
        for (auto& buf : buffer_pool_) {
            if (!buf.in_use) {
                buf.in_use = true;
                return &buf;
            }
        }
        return nullptr;
    }

    void release_buffer(ParseBuffer* buf) {
        std::lock_guard<std::mutex> lock(store_mutex_);
        if (buf) {
            memset(buf->data, 0, MAX_TOKEN_DATA_LEN);
            buf->in_use = false;
        }
    }

    std::string extract_session_id(const uint8_t* data, size_t len) {
        // Session ID is a null-terminated string at the start of payload
        size_t id_len = strnlen(reinterpret_cast<const char*>(data), std::min(len, (size_t)64));
        return std::string(reinterpret_cast<const char*>(data), id_len);
    }
};

} // namespace secure_session
